/* Scale features and walk every tree; class score = sum of leaf outputs.
 * Returns the arg-max class id (softmax arg-max == raw-margin arg-max). */
static int ids_predict(const float *raw) {
    float x[IDS_NUM_FEATURES];
    int i, t, n, best;
    float score[IDS_NUM_CLASS];
    for (i = 0; i < IDS_NUM_FEATURES; i++)
        x[i] = (raw[i] - IDS_MEAN[i]) / IDS_SCALE[i];
    for (i = 0; i < IDS_NUM_CLASS; i++) score[i] = 0.0f;
    for (t = 0; t < IDS_NUM_TREES; t++) {
        n = IDS_TREE_ROOT[t];
        while (IDS_NODES[n].feature >= 0)
            n = (x[IDS_NODES[n].feature] < IDS_NODES[n].value)
                ? IDS_NODES[n].yes : IDS_NODES[n].no;
        score[IDS_TREE_CLASS[t]] += IDS_NODES[n].value;
    }
    best = 0;
    for (i = 1; i < IDS_NUM_CLASS; i++)
        if (score[i] > score[best]) best = i;
    return best;
}

